insert into public.role_templates (key, label, level, permissions, default_scope_org_id, scope_mode, aggregate_only, read_only, building_scoped, sensitive_grants, can_invite, max_access_days, self_signup, explanation) values
  ('president', 'University President', 'Executive viewer', array['dashboard:view:institution', 'work_order:view:summary', 'organization:view', 'audit:view:summary', 'people:view', 'people:invite', 'people:manage']::text[], 'university', 'subtree', true, false, false, '{}'::text[], array['coo', 'vpStudentAffairs', 'housingDirector', 'itDirector', 'facilitiesDirector', 'healthCenterDirector', 'auditor', 'staffRequester']::text[], null, false, 'Institution-wide trends and approved aggregates. Leadership does not automatically receive every student or incident record.'),
  ('coo', 'Chief Operating Officer', 'Executive viewer', array['dashboard:view:operations', 'work_order:view:summary', 'organization:view', 'audit:view:summary', 'people:view', 'people:invite', 'people:manage']::text[], 'university-operations', 'subtree', true, false, false, '{}'::text[], array['itDirector', 'facilitiesDirector', 'staffRequester']::text[], null, false, 'Operational performance across IT, facilities, police, safety, and property—details remain purpose-limited.'),
  ('vpStudentAffairs', 'VP of Student Affairs', 'Division administrator', array['dashboard:view:division', 'work_order:view', 'work_order:view_internal', 'work_order:create', 'work_order:update', 'work_order:assign', 'resident:view_identity', 'floorplan:view', 'occupancy:view', 'organization:view', 'audit:view:department', 'people:view', 'people:invite', 'people:manage']::text[], 'student-affairs', 'subtree', false, false, false, '{}'::text[], array['housingDirector', 'healthCenterDirector', 'hallDirector', 'residentAssistant']::text[], null, false, 'Row-level access across Student Affairs, including Housing and its nested Maintenance team. Health, Counseling, and Conduct queues stay excluded without an explicit grant.'),
  ('housingDirector', 'Housing Director', 'Department administrator', array['dashboard:view:department', 'work_order:view', 'work_order:view_internal', 'work_order:create', 'work_order:update', 'work_order:assign', 'readiness:update', 'resident:view_identity', 'floorplan:view', 'occupancy:view', 'organization:view', 'audit:view:department', 'people:view', 'people:invite', 'people:manage']::text[], 'campus-living-housing', 'subtree', false, false, false, '{}'::text[], array['hallDirector', 'residentAssistant', 'maintenanceDispatcher', 'technician', 'contractor']::text[], null, false, 'Housing and every nested team, including Housing Maintenance. Can triage, update, and assign work inside this subtree.'),
  ('hallDirector', 'Residence Hall Director', 'Operator', array['dashboard:view:building', 'work_order:view', 'work_order:view_internal', 'work_order:create', 'work_order:update', 'readiness:update', 'resident:view_identity', 'floorplan:view', 'occupancy:view', 'organization:view', 'people:view', 'people:invite', 'people:manage']::text[], 'campus-living-housing', 'subtree', false, false, true, '{}'::text[], array['residentAssistant']::text[], null, false, 'Housing work, including nested maintenance, but only in the halls this person supervises. Can update status; dispatchers handle assignment.'),
  ('residentAssistant', 'Resident Assistant', 'Contributor', array['dashboard:view:building', 'work_order:view', 'work_order:create', 'floorplan:view', 'organization:view:limited']::text[], 'campus-living-housing', 'subtree', false, false, true, '{}'::text[], '{}'::text[], 365, false, 'Reports and follows issues in an assigned hall. Sees the floor plan but not occupancy, internal notes, or resident identities on others'' requests.'),
  ('maintenanceDispatcher', 'Housing Maintenance Dispatcher', 'Coordinator', array['dashboard:view:department', 'work_order:view', 'work_order:view_internal', 'work_order:create', 'work_order:update', 'work_order:assign', 'readiness:update', 'floorplan:view', 'organization:view', 'audit:view:department', 'people:view']::text[], 'housing-maintenance', 'subtree', false, false, false, '{}'::text[], '{}'::text[], null, false, 'Owns the housing maintenance queue and can assign work to technicians; cannot see unrelated IT or facilities records.'),
  ('technician', 'Maintenance Technician', 'Operator', array['dashboard:view:assigned', 'work_order:view', 'work_order:view_internal', 'work_order:update', 'floorplan:view', 'organization:view']::text[], 'housing-maintenance', 'assigned', false, false, false, '{}'::text[], '{}'::text[], null, false, 'Sees assigned jobs, location, floor plans, and entry instructions only. Cannot reassign, approve, or browse resident records.'),
  ('itDirector', 'IT Director', 'Department administrator', array['dashboard:view:department', 'work_order:view', 'work_order:view_internal', 'work_order:create', 'work_order:update', 'work_order:assign', 'floorplan:view', 'organization:view', 'audit:view:department', 'people:view', 'people:invite', 'people:manage']::text[], 'information-technology', 'subtree', false, false, false, '{}'::text[], array['itTechnician', 'contractor']::text[], null, false, 'IT service records and teams only. Housing maintenance work stays outside this role''s scope, even in residence halls.'),
  ('itTechnician', 'IT Technician', 'Operator', array['dashboard:view:assigned', 'work_order:view', 'work_order:view_internal', 'work_order:update', 'floorplan:view', 'organization:view']::text[], 'information-technology', 'assigned', false, false, false, '{}'::text[], '{}'::text[], null, false, 'Assigned IT tickets with location and device context. No resident identity or housing records.'),
  ('facilitiesDirector', 'Facilities Director', 'Department administrator', array['dashboard:view:department', 'work_order:view', 'work_order:view_internal', 'work_order:create', 'work_order:update', 'work_order:assign', 'floorplan:view', 'organization:view', 'audit:view:department', 'people:view', 'people:invite', 'people:manage']::text[], 'facilities-management', 'subtree', false, false, false, '{}'::text[], array['technician', 'contractor']::text[], null, false, 'Campus facilities work in the University Operations branch. Housing Maintenance remains separately scoped for the pilot.'),
  ('healthCenterDirector', 'Health Center Director', 'Department administrator', array['dashboard:view:department', 'work_order:view', 'work_order:view_internal', 'work_order:create', 'work_order:update', 'work_order:assign', 'organization:view', 'audit:view:department', 'people:view']::text[], 'health-center', 'subtree', false, false, false, '{}'::text[], '{}'::text[], null, false, 'A restricted unit''s own queue. Because the unit is marked sensitive, the VP of Student Affairs does not inherit these records.'),
  ('student', 'Student Resident', 'Personal self-service', array['dashboard:view:own', 'work_order:view', 'work_order:create', 'floorplan:view:own', 'organization:view:limited']::text[], null, 'own', false, false, false, '{}'::text[], '{}'::text[], null, true, 'Creates and follows personal requests; sees their own hall''s plan and published service status, with no staff-only notes.'),
  ('contractor', 'External Contractor', 'External restricted user', array['dashboard:view:assigned', 'work_order:view', 'work_order:update', 'floorplan:view']::text[], 'facilities-management', 'assigned', false, false, false, '{}'::text[], '{}'::text[], 90, false, 'Named jobs only, for a fixed contract window. Access expires automatically and cannot be extended past 90 days per invitation.'),
  ('staffRequester', 'Faculty / Staff Requester', 'Personal self-service', array['dashboard:view:own', 'work_order:view', 'work_order:create', 'organization:view:limited']::text[], null, 'own', false, false, false, '{}'::text[], '{}'::text[], null, false, 'Reports classroom and office problems and follows their own requests.'),
  ('auditor', 'Compliance Auditor', 'Auditor', array['dashboard:view:institution', 'work_order:view', 'work_order:view_internal', 'floorplan:view', 'organization:view', 'audit:view:institution', 'people:view']::text[], 'university', 'subtree', false, true, false, array['health-center', 'counseling', 'student-conduct', 'university-police']::text[], '{}'::text[], 180, false, 'Read-only access within an approved audit scope, including restricted units; export is intentionally excluded from this prototype.')
